/**
 * PolicyList Component
 * 
 * Sidebar component for displaying the list of policies with API integration.
 */

import { useState, useEffect, useCallback } from "react";
import { useTheme } from "@astryxdesign/core";
import type { Policy } from "../types/policy";

interface PolicyListProps {
  selectedPolicyId?: string;
  onPolicySelect?: (policy: Policy) => void;
  onPolicyEdit?: (policy: Policy) => void;
  onPolicyDelete?: (policyId: string) => void;
  onNewPolicy?: () => void;
}

/**
 * Policy list item component
 */
interface PolicyListItemProps {
  policy: Policy;
  isSelected: boolean;
  onClick: () => void;
  onEdit?: () => void;
  onDelete?: () => void;
}

const PolicyListItem: React.FC<PolicyListItemProps> = ({
  policy,
  isSelected,
  onClick,
  onEdit,
  onDelete,
}) => {
  const theme = useTheme();
  const t = (name: string) => theme.token(name);

  const itemStyle: React.CSSProperties = {
    padding: "0.875rem 1rem",
    borderRadius: t("--radius-element"),
    backgroundColor: isSelected ? t("--color-accent") : "transparent",
    color: isSelected ? "white" : t("--color-text-primary"),
    cursor: "pointer",
    transition: `all ${theme.tokens["--duration-fast"] || "150ms"}`,
    marginBottom: "0.5rem",
    border: `1px solid ${isSelected ? t("--color-accent") : "transparent"}`,
  };

  const titleStyle: React.CSSProperties = {
    fontSize: "0.875rem",
    fontWeight: 500,
    marginBottom: "0.25rem",
    overflow: "hidden",
    textOverflow: "ellipsis",
    whiteSpace: "nowrap" as const,
  };

  const metaStyle: React.CSSProperties = {
    fontSize: "0.75rem",
    color: isSelected ? "rgba(255,255,255,0.8)" : t("--color-text-secondary"),
    overflow: "hidden",
    textOverflow: "ellipsis",
    whiteSpace: "nowrap" as const,
  };

  const actionsStyle: React.CSSProperties = {
    display: "flex",
    gap: "0.25rem",
    marginTop: "0.5rem",
  };

  const actionButtonStyle: React.CSSProperties = {
    padding: "0.25rem 0.5rem",
    fontSize: "0.625rem",
    borderRadius: t("--radius-inner"),
    border: "none",
    cursor: "pointer",
    opacity: isSelected ? 0.9 : 1,
    backgroundColor: isSelected ? "rgba(255,255,255,0.2)" : t("--color-background-muted"),
    color: isSelected ? "white" : t("--color-text-secondary"),
  };

  return (
    <div style={itemStyle} onClick={onClick}>
      <div style={titleStyle}>{policy.name}</div>
      <div style={metaStyle}>
        {new Date(policy.createdAt).toLocaleDateString()} • {policy.description || "설명 없음"}
      </div>
      {(onEdit || onDelete) && (
        <div style={actionsStyle} onClick={(e) => e.stopPropagation()}>
          {onEdit && (
            <button style={actionButtonStyle} onClick={onEdit}>
              수정
            </button>
          )}
          {onDelete && (
            <button style={actionButtonStyle} onClick={onDelete}>
              삭제
            </button>
          )}
        </div>
      )}
    </div>
  );
};

/**
 * PolicyList Component
 */
export const PolicyList: React.FC<PolicyListProps> = ({
  selectedPolicyId,
  onPolicySelect,
  onPolicyEdit,
  onPolicyDelete,
  onNewPolicy,
}) => {
  const theme = useTheme();
  const t = (name: string) => theme.token(name);

  // State
  const [policies, setPolicies] = useState<Policy[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");

  // Fetch policies from API
  const fetchPolicies = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const response = await fetch("/api/policies");

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();
      setPolicies(data.policies || []);
    } catch (err) {
      // If API is not available, use mock data for demo
      console.warn("API not available, using mock data:", err);
      setPolicies(getMockPolicies());
    } finally {
      setLoading(false);
    }
  }, []);

  // Initial fetch
  useEffect(() => {
    fetchPolicies();
  }, [fetchPolicies]);

  // Filter policies by search term
  const filteredPolicies = policies.filter(
    (policy) =>
      policy.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      policy.description?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Handle new policy button
  const handleNewPolicy = () => {
    if (onNewPolicy) {
      onNewPolicy();
    }
  };

  // Styles
  const containerStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    height: "100%",
    backgroundColor: t("--color-background-surface"),
    borderRight: `1px solid ${t("--color-border")}`,
  };

  const headerStyle: React.CSSProperties = {
    padding: "1rem",
    borderBottom: `1px solid ${t("--color-border")}`,
  };

  const titleStyle: React.CSSProperties = {
    fontSize: "1rem",
    fontWeight: 600,
    color: t("--color-text-primary"),
    marginBottom: "0.75rem",
  };

  const searchStyle: React.CSSProperties = {
    width: "100%",
    padding: "0.5rem 0.75rem",
    fontSize: "0.875rem",
    borderRadius: t("--radius-element"),
    border: `1px solid ${t("--color-border")}`,
    backgroundColor: t("--color-background-body"),
    color: t("--color-text-primary"),
    outline: "none",
    boxSizing: "border-box" as const,
  };

  const newButtonStyle: React.CSSProperties = {
    width: "100%",
    padding: "0.625rem 1rem",
    fontSize: "0.875rem",
    fontWeight: 500,
    borderRadius: t("--radius-element"),
    border: "none",
    backgroundColor: t("--color-accent"),
    color: "white",
    cursor: "pointer",
    marginTop: "0.75rem",
    transition: `background-color ${theme.tokens["--duration-fast"] || "150ms"}`,
  };

  const listContainerStyle: React.CSSProperties = {
    flex: 1,
    overflowY: "auto" as const,
    padding: "1rem",
  };

  const emptyStateStyle: React.CSSProperties = {
    textAlign: "center",
    padding: "2rem 1rem",
    color: t("--color-text-secondary"),
  };

  const errorStyle: React.CSSProperties = {
    padding: "0.75rem 1rem",
    margin: "1rem",
    borderRadius: t("--radius-element"),
    backgroundColor: "#fef2f2",
    color: "#dc2626",
    fontSize: "0.875rem",
  };

  const loadingStyle: React.CSSProperties = {
    padding: "2rem 1rem",
    textAlign: "center",
    color: t("--color-text-secondary"),
  };

  // Mock data for demo
  function getMockPolicies(): Policy[] {
    return [
      {
        id: "policy-001",
        name: "Admin Document Access",
        cedarJson: '{"effect":"forbid","principal":{"role":"admin"},"resource":{"type":"document"},"action":"delete"}',
        description: "관리자 문서 삭제 제한",
        createdAt: "2026-07-24T09:00:00Z",
        updatedAt: "2026-07-24T09:00:00Z",
      },
      {
        id: "policy-002",
        name: "Viewer Read Only",
        cedarJson: '{"effect":"forbid","principal":{"role":"viewer"},"resource":{"type":"document"},"action":"write"}',
        description: "뷰어 쓰기 제한",
        createdAt: "2026-07-23T14:30:00Z",
        updatedAt: "2026-07-23T14:30:00Z",
      },
      {
        id: "policy-003",
        name: "Issue Editor Restriction",
        cedarJson: '{"effect":"forbid","principal":{"role":"editor"},"resource":{"type":"issue"},"action":"delete"}',
        description: "편집자 이슈 삭제 제한",
        createdAt: "2026-07-22T10:15:00Z",
        updatedAt: "2026-07-22T10:15:00Z",
      },
    ];
  }

  return (
    <div style={containerStyle}>
      <div style={headerStyle}>
        <h3 style={titleStyle}>Policies</h3>
        <input
          type="text"
          placeholder="정책 검색..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={searchStyle}
        />
        <button style={newButtonStyle} onClick={handleNewPolicy}>
          + 새 정책
        </button>
      </div>

      <div style={listContainerStyle}>
        {loading && <div style={loadingStyle}>로딩 중...</div>}

        {error && <div style={errorStyle}>{error}</div>}

        {!loading && !error && filteredPolicies.length === 0 && (
          <div style={emptyStateStyle}>
            <p>정책이 없습니다.</p>
            <p style={{ fontSize: "0.75rem", marginTop: "0.5rem" }}>
              "새 정책" 버튼을 클릭하여 첫 번째 정책을 만드세요.
            </p>
          </div>
        )}

        {!loading &&
          !error &&
          filteredPolicies.map((policy) => (
            <PolicyListItem
              key={policy.id}
              policy={policy}
              isSelected={policy.id === selectedPolicyId}
              onClick={() => onPolicySelect?.(policy)}
              onEdit={onPolicyEdit ? () => onPolicyEdit(policy) : undefined}
              onDelete={onPolicyDelete ? () => onPolicyDelete(policy.id) : undefined}
            />
          ))}
      </div>
    </div>
  );
};

/**
 * Playground Page
 * 
 * 메인 Playground 레이아웃:
 * - 좌측 사이드바: Policy List
 * - 우측 메인 콘텐츠: Policy Editor / Test Panel 전환
 * - 하단: Result Display
 */

import { useState, useCallback } from "react";
import { useTheme } from "@astryxdesign/core";
import { PolicyList } from "../components/PolicyList";
import { PolicyEditor } from "../components/PolicyEditor";
import { TestPanel } from "../components/TestPanel";
import type { Policy } from "../types/policy";

/**
 * Playground Page View Modes
 */
type PlaygroundView = "editor" | "test";

/**
 * Playground Page Props
 */
export interface PlaygroundProps {
  // 초기 선택 정책
  initialPolicy?: Policy;
}

/**
 * Playground Page Component
 */
export const Playground: React.FC<PlaygroundProps> = ({ initialPolicy }) => {
  const theme = useTheme();
  const t = (name: string) => theme.token(name);

  // State
  const [selectedPolicy, setSelectedPolicy] = useState<Policy | null>(initialPolicy || null);
  const [activeView, setActiveView] = useState<PlaygroundView>("test");
  const [isCreatingNew, setIsCreatingNew] = useState(false);

  // Handle policy selection from sidebar
  const handlePolicySelect = useCallback((policy: Policy) => {
    setSelectedPolicy(policy);
    setActiveView("editor");
    setIsCreatingNew(false);
  }, []);

  // Handle new policy creation
  const handleNewPolicy = useCallback(() => {
    setSelectedPolicy(null);
    setActiveView("editor");
    setIsCreatingNew(true);
  }, []);

  // Handle policy save
  const handleSavePolicy = useCallback(async (cedarJson: string, name: string) => {
    console.log("Saving policy:", { name, cedarJson });

    // API 호출 로직
    try {
      const response = await fetch("/api/policies", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          name,
          cedarJson,
          description: `Forbid 정책 - ${name}`,
        }),
      });

      if (response.ok) {
        const data = await response.json();
        console.log("Policy saved:", data);
        alert(`정책 "${name}"이(가) 저장되었습니다!`);
        setSelectedPolicy(data.policy);
        setIsCreatingNew(false);
      } else {
        // API가 없으면 Mock으로 처리
        console.warn("API not available, simulating save");
        alert(`정책 "${name}"이(가) 저장되었습니다! (데모 모드)`);
        setIsCreatingNew(false);
      }
    } catch (error) {
      // API가 없으면 Mock으로 처리
      console.warn("API not available, simulating save:", error);
      alert(`정책 "${name}"이(가) 저장되었습니다! (데모 모드)`);
      setIsCreatingNew(false);
    }
  }, []);

  // Handle policy edit
  const handlePolicyEdit = useCallback((policy: Policy) => {
    setSelectedPolicy(policy);
    setActiveView("editor");
    setIsCreatingNew(false);
  }, []);

  // Handle policy delete
  const handlePolicyDelete = useCallback(async (policyId: string) => {
    if (!confirm("이 정책을 삭제하시겠습니까?")) {
      return;
    }

    try {
      const response = await fetch(`/api/policies/${policyId}`, {
        method: "DELETE",
      });

      if (response.ok || response.status === 404) {
        alert("정책이 삭제되었습니다.");
        if (selectedPolicy?.id === policyId) {
          setSelectedPolicy(null);
        }
      } else {
        console.warn("API not available, simulating delete");
        alert("정책이 삭제되었습니다. (데모 모드)");
        if (selectedPolicy?.id === policyId) {
          setSelectedPolicy(null);
        }
      }
    } catch (error) {
      console.warn("API not available, simulating delete:", error);
      alert("정책이 삭제되었습니다. (데모 모드)");
      if (selectedPolicy?.id === policyId) {
        setSelectedPolicy(null);
      }
    }
  }, [selectedPolicy]);

  // Handle cancel
  const handleCancel = useCallback(() => {
    setSelectedPolicy(null);
    setIsCreatingNew(false);
    setActiveView("test");
  }, []);

  // Styles
  const containerStyle: React.CSSProperties = {
    display: "flex",
    height: "100vh",
    backgroundColor: t("--color-background-body"),
  };

  const sidebarStyle: React.CSSProperties = {
    width: "300px",
    flexShrink: 0,
    height: "100%",
  };

  const mainContentStyle: React.CSSProperties = {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    overflow: "hidden",
  };

  const headerStyle: React.CSSProperties = {
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    padding: "1rem 1.5rem",
    backgroundColor: t("--color-background-surface"),
    borderBottom: `1px solid ${t("--color-border")}`,
  };

  const titleStyle: React.CSSProperties = {
    fontSize: "1.125rem",
    fontWeight: 600,
    color: t("--color-text-primary"),
    margin: 0,
  };

  const tabContainerStyle: React.CSSProperties = {
    display: "flex",
    gap: "0.25rem",
    padding: "0.5rem 1.5rem",
    backgroundColor: t("--color-background-surface"),
    borderBottom: `1px solid ${t("--color-border")}`,
  };

  const tabStyle = (isActive: boolean): React.CSSProperties => ({
    padding: "0.625rem 1.25rem",
    fontSize: "0.875rem",
    fontWeight: isActive ? 600 : 400,
    color: isActive ? t("--color-accent") : t("--color-text-secondary"),
    backgroundColor: "transparent",
    border: "none",
    borderBottom: isActive ? `2px solid ${t("--color-accent")}` : "2px solid transparent",
    cursor: "pointer",
    transition: `all ${theme.tokens["--duration-fast"] || "150ms"}`,
  });

  const contentStyle: React.CSSProperties = {
    flex: 1,
    padding: "1.5rem",
    overflowY: "auto" as const,
  };

  const emptyStateStyle: React.CCSSProperties = {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    height: "100%",
    color: t("--color-text-secondary"),
    textAlign: "center",
  };

  const emptyStateTitleStyle: React.CSSProperties = {
    fontSize: "1.25rem",
    fontWeight: 600,
    color: t("--color-text-primary"),
    marginBottom: "0.5rem",
  };

  const emptyStateButtonStyle: React.CSSProperties = {
    marginTop: "1rem",
    padding: "0.75rem 1.5rem",
    fontSize: "0.875rem",
    fontWeight: 500,
    borderRadius: t("--radius-element"),
    border: "none",
    backgroundColor: t("--color-accent"),
    color: "white",
    cursor: "pointer",
  };

  return (
    <div style={containerStyle}>
      {/* Policy List Sidebar */}
      <div style={sidebarStyle}>
        <PolicyList
          selectedPolicyId={selectedPolicy?.id}
          onPolicySelect={handlePolicySelect}
          onPolicyEdit={handlePolicyEdit}
          onPolicyDelete={handlePolicyDelete}
          onNewPolicy={handleNewPolicy}
        />
      </div>

      {/* Main Content Area */}
      <div style={mainContentStyle}>
        {/* Header */}
        <div style={headerStyle}>
          <h1 style={titleStyle}>
            {selectedPolicy
              ? selectedPolicy.name
              : isCreatingNew
              ? "새 정책 만들기"
              : "Playground"}
          </h1>
          {selectedPolicy && !isCreatingNew && (
            <span
              style={{
                fontSize: "0.75rem",
                padding: "0.25rem 0.75rem",
                borderRadius: t("--radius-inner"),
                backgroundColor: t("--color-accent"),
                color: "white",
              }}
            >
              선택됨
            </span>
          )}
        </div>

        {/* Tab Navigation */}
        <div style={tabContainerStyle}>
          <button
            style={tabStyle(activeView === "editor")}
            onClick={() => setActiveView("editor")}
          >
            Policy Editor
          </button>
          <button
            style={tabStyle(activeView === "test")}
            onClick={() => setActiveView("test")}
          >
            Test Panel
          </button>
        </div>

        {/* Content */}
        <div style={contentStyle}>
          {activeView === "editor" ? (
            selectedPolicy || isCreatingNew ? (
              <PolicyEditor
                initialData={
                  selectedPolicy
                    ? parseCedarJson(selectedPolicy.cedarJson)
                    : undefined
                }
                onSave={handleSavePolicy}
                onCancel={handleCancel}
              />
            ) : (
              <div style={emptyStateStyle}>
                <p style={emptyStateTitleStyle}>편집할 정책을 선택하세요</p>
                <p>사이드바에서 정책을 선택하거나 새 정책을 만드세요.</p>
                <button style={emptyStateButtonStyle} onClick={handleNewPolicy}>
                  + 새 정책 만들기
                </button>
              </div>
            )
          ) : (
            <TestPanel />
          )}
        </div>
      </div>
    </div>
  );
};

/**
 * Cedar JSON 파싱 헬퍼
 */
function parseCedarJson(cedarJson: string): {
  principal?: { role?: string };
  resource?: { type?: string };
  action?: string;
  condition?: { expression?: string; description?: string };
} | undefined {
  try {
    return JSON.parse(cedarJson);
  } catch {
    return undefined;
  }
}

